window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3857052b72ac64de"]={"versions": [{"id": "FIG-3857052b72ac64de", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm bzw. Ablaufdiagramm (Flowchart) zur Spezifikation des Koordinationsalgorithmus für den koordinierten Netzwerk-Shutdown im AUTOSAR-Basissoftwaremodul Network Management Interface (<code>Nm</code>). Das Diagramm beschreibt die algorithmische Kontrollflusslogik beim Übergang mehrerer koordinierter Netzwerkcluster und des lokalen Steuergeräteknotens in den Ruhezustand (Bus-Sleep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Nm-Koordinator / Nm-Interface</strong>: Zentrale Steuerungslogik des <code>Nm</code>-Moduls zur netzwerkübergreifenden Koordination.</li>\n<li><strong>Entitäten</strong>:</li>\n<li>Lokaler Knoten und zugehörige Netzwerkcluster.</li>\n<li>Shutdown-Delay-Timer (ein Timer pro koordiniertem Netzwerkcluster).</li>\n<li>Synchronisationsindikationen (NM-Synchronisationsmeldungen über den Bus).</li>\n<li><strong>Schnittstellen / Aktionen</strong>:</li>\n<li>Abfrage der Schlafbereitschaft aller Netzwerke und des Knotens.</li>\n<li>Empfang der Synchronisationsindikation (optionaler Pfad).</li>\n<li>Starten der Shutdown-Delay-Timer.</li>\n<li>Shutdown-Befehl für das jeweilige Netzwerk nach Ablauf des spezifischen Timers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Eintritt über den Initialknoten in die Entscheidung „All networks and node itself ready for sleep?“.</li>\n<li><strong>Schlafbereitschaftsprüfung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[No]</code>: Schleife zurück zur erneuten Prüfung.</li>\n<li>Wenn <code>[Yes]</code>: Übergang zur Synchronisation oder direkt zum Timer-Start.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation (optional)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pfad A: Warten auf eine gültige Synchronisationsindikation („Wait for valid synchronization indication“).</li>\n<li>Pfad B: Bypass direkt zum Starten der Shutdown-Delay-Timer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Timer-Initialisierung</strong>: Ausführen von „Start all Shutdown-delay-timers“.</li>\n<li><strong>Timer-Ablaufschema</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintreten in „Wait for a new timer to expire“.</li>\n<li>Sobald ein Timer abläuft: Ausführen von „Command Shutdown for the network with recently expired timer“.</li>\n<li>Prüfung „All Timers Expired?“:</li>\n<li>Wenn <code>[No]</code>: Rückverzweigung zu „Wait for a new timer to expire“.</li>\n<li>Wenn <code>[Yes]</code>: Übergang zur finalen Ruhephase.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss</strong>: Ausführen von „Wait until all networks are asleep“ und Übergang zum Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ die Ablaufreihenfolge des Koordinationsalgorithmus beim koordinierten Herunterfahren von Netzwerken im <code>Nm</code>. Relevante Aspekte für die Implementierung:</p>\n<ul class=\"fig-list\">\n<li>Der Algorithmus darf Shutdown-Delay-Timer erst starten, wenn sowohl alle zu koordinierenden Netzwerke als auch die lokale ECU bereit für den Schlafmodus sind.</li>\n<li>Die Auswertung der Synchronisationsindikation ist als optionaler Kontrollflusspfad modelliert, der umgangen werden kann.</li>\n<li>Das Herunterfahren einzelner Netzwerke erfolgt zeitversetzt und sequentiell basierend auf dem jeweiligen Timer-Ablauf.</li>\n<li>Der Gesamtvorgang ist erst abgeschlossen, wenn alle Timer abgelaufen sind und alle beteiligten Busse physisch den Schlafzustand erreicht haben.</li>\n</ul>"}, {"id": "FIG-0e7dddf000ea3c78", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm bzw. Ablaufdiagramm (Flowchart) zur Spezifikation des Koordinationsalgorithmus für den koordinierten Netzwerk-Shutdown im AUTOSAR-Basissoftwaremodul Network Management Interface (<code>Nm</code>). Das Diagramm beschreibt die algorithmische Kontrollflusslogik beim Übergang mehrerer koordinierter Netzwerkcluster und des lokalen Steuergeräteknotens in den Ruhezustand (Bus-Sleep).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Nm-Koordinator / Nm-Interface</strong>: Zentrale Instanz zur netzwerkübergreifenden Shutdown-Koordination.</li>\n<li><strong>Beteiligte Softwareschnittstellen & APIs</strong>:</li>\n<li><code>BusNm_BusSynchronization</code>: Busspezifische Synchronisations-API (z. B. CanNm/FrNm).</li>\n<li><code>BusNm_NetworkRelease</code>: Busspezifische Freigabe des Netzwerks zum Einschlafen.</li>\n<li><code>Nm_BusSleepMode</code>: Callback bzw. Benachrichtigung an höhere Schichten über das Erreichen des Bus-Sleep-Modus.</li>\n<li><strong>Entitäten</strong>:</li>\n<li>Koordinierte Netzwerke und lokaler Knoten.</li>\n<li>Shutdown-Delay-Timer je Netzwerkcluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Eintritt über den Start-Pseudozustand in die Entscheidungsraute „all networks and node itself ready for sleep?“.</li>\n<li><strong>Schlafbereitschaftsprüfung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>No</code>: Schleife zurück zur zyklischen Re-Evaluation.</li>\n<li>Wenn <code>Yes</code>: Weiterschaltung zu „wait vor valid synchronization indication (optional step)“.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationsschritt</strong>: Warten auf die Synchronisationsindikation im sequentiellen Ablaufpfad.</li>\n<li><strong>Timer-Initialisierung</strong>: Übergang zu „start all shutdown delay timers“.</li>\n<li><strong>Timer-Ablaufschema</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in „wait for next timer to expire“.</li>\n<li>Nach Ablauf eines Timers: Aufruf von <code>BusNm_BusSynchronization</code> gefolgt von <code>BusNm_NetworkRelease</code> für das spezifisch zugeordnete Netzwerk.</li>\n<li>Entscheidungsraute „all timers expired?“:</li>\n<li>Wenn <code>No</code>: Rückführung zu „wait for next timer to expire“.</li>\n<li>Wenn <code>Yes</code>: Übergang zu „Wait for all Networks to go to sleep and calling Nm_BusSleepMode“.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss</strong>: Warten, bis alle Netzwerke schlafen, gefolgt vom Aufruf von <code>Nm_BusSleepMode</code>, und Übergang in den Endzustand (<code>End</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ die verbindlichen API-Aufrufe während des koordinierten Herunterfahrens fest:</p>\n<ul class=\"fig-list\">\n<li>Nach Ablauf eines Shutdown-Delay-Timers muss zwingend zuerst <code>BusNm_BusSynchronization</code> und unmittelbar danach <code>BusNm_NetworkRelease</code> des zugehörigen Netzwerks aufgerufen werden.</li>\n<li>Ein Bypass-Pfad um den Synchronisationsschritt ist im Kontrollfluss nicht mehr als Verzweigung modelliert; der Schritt ist sequentiell eingeordnet.</li>\n<li>Nach Ablauf aller Shutdown-Delay-Timer und dem Einschlafen aller beteiligten Netzwerke ist explizit <code>Nm_BusSleepMode</code> aufzurufen.</li>\n</ul>"}], "trans": [{"from": "FIG-3857052b72ac64de", "to": "FIG-0e7dddf000ea3c78", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Optionaler Synchronisationsschritt („wait vor valid synchronization indication (optional step)“)</strong>: Der Bypass-Zweig um diesen Schritt entfällt; der Schritt ist nun als fester Knoten im linearen Ablaufpfad integriert (mit redaktionellem Tippfehler „vor“ statt „for“).</li>\n<li><strong>Aktion nach Timerablauf</strong>: Ersetzung der generischen Shutdown-Anweisung („Command Shutdown for the network with recently expired timer“) durch die konkreten Funktionsaufrufe <code>BusNm_BusSynchronization</code> gefolgt von <code>BusNm_NetworkRelease</code> für das dem abgelaufenen Timer zugeordnete Netzwerk.</li>\n<li><strong>Abschlussaktion</strong>: Ergänzung des Aufrufs von <code>Nm_BusSleepMode</code> im Schritt „Wait for all Networks to go to sleep and calling Nm_BusSleepMode“ (zuvor rein passives „Wait until all networks are asleep“).</li>\n<li><strong>Start- und Endknoten</strong>: Beschriftung der UML-Pseudozustände mit „Start“ und „End“.</li>\n</ul>"}]};
